 54→              <span class="role-card__rec-role">{{ rec.roleLabel }}:</span>
 55→              @if (rec.selection) {
 56→                <span class="role-card__rec-selection">{{ rec.selection }}</span>
 57→              } @else {
 58→                <span class="role-card__rec-pending">pending...</span>
 59→              }
 60→            </div>
 61→          }
 62→        </div>
 63→      }
 64→
 65→      <!-- Decision Form (active only) -->
 66→      @if (card().decision && card().status === 'active') {
 67→        <div class="role-card__decision">
 68→          @if (questionType() === 'single_choice' || questionType() === 'multi_choice') {
 69→            @for (option of filteredOptions(); track option.id) {
 70→              <label class="role-card__option" [class.role-card__option--selected]="isSelected(option.id)">
 71→                <input
